import React from 'react';
import {AbsoluteFill} from 'remotion';
import {useS, en, Camara, Subtitulos, Textura, Profundidad, Brillo, Paso, Recorrido, seguir, enCamino, Chip, Regla, Contador, Ondas, golpe, h, tono, ventana, clamp, interpolate, Easing} from './kit';

export const SUBS = {arriba: 230, acento: '#E7FF00'};

// ---- tiempos atados a la voz ----
const MANOS = en('manos'), ECHARON = en('echaron'), IGNAZ = en('Ignaz'), VIENA = en('Viena'), H2 = en('hospital', 2), SALAS = en('salas');
const PARTE = en('parteras'), MAS = en('más'), MED2 = en('médicos', 2), DOBLE = en('doble'), MUJERES = en('mujeres'), SUPLIC = en('suplicaban');
const ENTONCES = en('Entonces'), COLEGA = en('colega'), BISTURI = en('bisturí'), MURIO = en('Murió'), FIEBRE = en('fiebre', 2), AHI = en('Ahí');
const VENIAN = en('venían'), PARTOS = en('partos'), INVIS = en('invisible'), PUSO = en('Puso'), AGUA = en('agua'), CLORO = en('cloro');
const NADIE = en('Nadie'), LAVAR2 = en('lavarse', 2), MUERTES = en('muertes'), UNO = en('uno'), PERO = en('Pero'), SUCIAS = en('sucias');
const INSULTO = en('insulto'), SACARON = en('sacaron'), GERM = en('gérmenes'), HOY = en('Hoy'), PALAN2 = en('palangana', 2);
const DALE = en('Dale'), SALE = en('sale'), BANO = en('baño');

const SEP = '#C9B98E', GRIS = '#6E7462', VERDE = '#8DAA5C', AZUL = '#7FC8FF', PIEL = '#E3B48F', CONTORNO = '#B9805D';

// los tiempos de cámara deben crecer siempre
const ord = (ps: {t: number; x: number; y: number; zoom: number}[]) => {
  let last = -1;
  return ps.map((p) => {
    const t = Math.max(p.t, last + 0.05);
    last = t;
    return {...p, t};
  });
};

const Lienzo: React.FC<{children: React.ReactNode}> = ({children}) => (
  <svg width={1080} height={1920} style={{position: 'absolute', inset: 0, overflow: 'visible'}}>{children}</svg>
);
const Capa: React.FC<{a: number; filtro?: string; children: React.ReactNode}> = ({a, filtro, children}) =>
  a <= 0.001 ? null : <AbsoluteFill style={{opacity: a, filter: filtro}}>{children}</AbsoluteFill>;

const Nieve: React.FC<{n?: number; op?: number}> = ({n = 36, op = 0.85}) => {
  const {s} = useS();
  return (
    <>
      {Array.from({length: n}).map((_, i) => {
        const x = (h(i) * 1200 - 60 + Math.sin(s * 0.9 + i) * 22);
        const y = (h(i + 50) * 2300 - 200 + s * (70 + h(i + 9) * 90)) % 2300 - 200;
        return <circle key={i} cx={x} cy={y} r={3 + h(i + 21) * 5} fill="#fff" opacity={op} />;
      })}
    </>
  );
};

// palangana de porcelana: la protagonista
const Palangana: React.FC<{x: number; y: number; sc?: number; agua?: number; glow?: number; rot?: number}> = ({x, y, sc = 1, agua = 0, glow = 0, rot = 0}) => (
  <g transform={`translate(${x} ${y}) rotate(${rot}) scale(${sc})`}>
    {glow > 0.01 && <ellipse cx={0} cy={30} rx={330} ry={190} fill="rgba(127,200,255,0.32)" opacity={glow} />}
    <ellipse cx={0} cy={158} rx={170} ry={26} fill="rgba(0,0,0,0.28)" />
    <path d="M -200 0 C -192 110 -130 152 0 152 C 130 152 192 110 200 0 Z" fill="#F2EFE6" stroke="#9A9684" strokeWidth={5} />
    <path d="M -190 34 C -168 108 -120 134 0 134 C 120 134 168 108 190 34" stroke="#5C86B5" strokeWidth={7} fill="none" />
    <ellipse cx={0} cy={0} rx={200} ry={56} fill="#FBF9F2" stroke="#9A9684" strokeWidth={5} />
    <ellipse cx={0} cy={4} rx={176} ry={44} fill="#CFC9BA" />
    {agua > 0.01 && (
      <g>
        <ellipse cx={0} cy={14 - agua * 14} rx={172} ry={42} fill={AZUL} opacity={Math.min(1, agua * 2.5)} />
        <ellipse cx={-40} cy={8 - agua * 14} rx={80} ry={12} fill="#fff" opacity={0.35 * Math.min(1, agua * 2.5)} />
      </g>
    )}
    <ellipse cx={-120} cy={-10} rx={36} ry={7} fill="#fff" opacity={0.5} />
  </g>
);

// mano de médico con levita, apunta hacia abajo; puntos = gérmenes verdes sobre la piel
const Mano: React.FC<{x: number; y: number; sc?: number; espejo?: boolean; rot?: number; puntos?: number; pOp?: number; manga?: boolean}> = ({x, y, sc = 1, espejo = false, rot = 0, puntos = 0, pOp = 1, manga = true}) => {
  const {s} = useS();
  return (
    <g transform={`translate(${x} ${y}) rotate(${rot}) scale(${(espejo ? -1 : 1) * sc} ${sc})`}>
      {manga && (
        <>
          <rect x={-58} y={-330} width={116} height={260} fill="#1B1B1B" />
          <rect x={-54} y={-76} width={108} height={34} rx={8} fill="#F3F0E8" stroke="#B9B3A4" strokeWidth={3} />
        </>
      )}
      {[[-36, 56, 64], [-12, 60, 78], [12, 60, 82], [36, 56, 66]].map(([fx, fy, L], i) => (
        <rect key={i} x={fx - 11} y={fy} width={22} height={L} rx={11} fill={PIEL} stroke={CONTORNO} strokeWidth={4} />
      ))}
      <ellipse cx={-58} cy={20} rx={16} ry={38} fill={PIEL} stroke={CONTORNO} strokeWidth={4} transform="rotate(25 -58 20)" />
      <rect x={-48} y={-46} width={96} height={108} rx={34} fill={PIEL} stroke={CONTORNO} strokeWidth={4} />
      <path d="M -30 -10 C -10 -20 10 -20 30 -10 M -26 14 C -8 6 8 6 26 14" stroke="rgba(150,100,70,0.35)" strokeWidth={3} fill="none" />
      {Array.from({length: puntos}).map((_, i) => (
        <circle key={i} cx={(h(i + 3) - 0.5) * 84 + Math.sin(s * 2.2 + i) * 7} cy={h(i + 40) * 150 - 30 + Math.cos(s * 2.6 + i * 1.7) * 7} r={4.5} fill="#5E9B2B" opacity={pOp} />
      ))}
    </g>
  );
};

// médico de 1847: bigote, levita, moño
const Medico: React.FC<{x: number; y: number; sc?: number; piel?: string; pelo?: string; enojo?: number}> = ({x, y, sc = 1, piel = PIEL, pelo = '#3A2A1E', enojo = 0}) => (
  <g transform={`translate(${x} ${y}) scale(${sc})`}>
    <path d="M -140 300 L -140 190 C -140 120 -80 92 0 92 C 80 92 140 120 140 190 L 140 300 Z" fill="#1C1C1C" stroke="#000" strokeWidth={4} />
    <path d="M -34 92 L 34 92 L 0 200 Z" fill="#F3F0E8" />
    <path d="M -22 108 L 22 108 L 14 132 L -14 132 Z" fill="#7A1D1D" />
    <rect x={-26} y={70} width={52} height={36} rx={14} fill={piel} />
    <ellipse cx={-70} cy={6} rx={14} ry={22} fill={piel} />
    <ellipse cx={70} cy={6} rx={14} ry={22} fill={piel} />
    <ellipse cx={0} cy={0} rx={68} ry={86} fill={piel} stroke="rgba(0,0,0,0.25)" strokeWidth={4} />
    <path d="M -72 -8 C -80 -104 80 -104 72 -8 C 60 -62 -60 -62 -72 -8 Z" fill={pelo} />
    {[-1, 1].map((d) => (
      <g key={d}>
        <ellipse cx={d * 28} cy={-6} rx={11} ry={8} fill="#fff" />
        <circle cx={d * 28} cy={-5} r={5} fill="#2a1a10" />
        <path d={`M ${d * 46} ${-30 - enojo * 6} L ${d * 12} ${-26 + enojo * 9}`} stroke={pelo} strokeWidth={7} strokeLinecap="round" />
      </g>
    ))}
    <path d="M 0 -4 Q -9 22 4 26" stroke="#B9805D" strokeWidth={4} fill="none" strokeLinecap="round" />
    <path d="M 0 38 C -20 24 -50 30 -58 48 C -36 40 -18 42 0 46 C 18 42 36 40 58 48 C 50 30 20 24 0 38 Z" fill={pelo} />
    <path d={`M -16 64 Q 0 ${enojo > 0.2 ? 56 : 70} 16 64`} stroke="#6A2A2A" strokeWidth={5} fill="none" strokeLinecap="round" />
  </g>
);

// puerta grande de hospital; cierre 0 = abierta, 1 = cerrada
const ARCO = 'M -300 0 L -300 -640 Q -300 -800 0 -800 Q 300 -800 300 -640 L 300 0 Z';
const Puerta: React.FC<{cierre: number; id: string}> = ({cierre, id}) => {
  const hoja = 36 + 264 * cierre;
  const Hoja = () => (
    <g>
      <rect x={0} y={-800} width={300} height={800} fill="#6B4A2E" />
      {[75, 150, 225].map((px) => <line key={px} x1={px} y1={-800} x2={px} y2={0} stroke="rgba(0,0,0,0.3)" strokeWidth={5} />)}
      <rect x={0} y={-610} width={300} height={22} fill="#2E2A24" />
      <rect x={0} y={-290} width={300} height={22} fill="#2E2A24" />
      <circle cx={264} cy={-360} r={14} fill="#C9A24A" stroke="#6A5420" strokeWidth={3} />
    </g>
  );
  return (
    <g transform="translate(540 1330)">
      <path d="M -344 44 L -344 -650 Q -344 -854 0 -854 Q 344 -854 344 -650 L 344 44 Z" fill="#8E8670" stroke="#5E5844" strokeWidth={8} />
      <path d={ARCO} fill="#241A10" />
      <ellipse cx={0} cy={-300} rx={210} ry={330} fill="rgba(255,200,120,0.4)" opacity={1 - cierre} />
      <clipPath id={id + 'c'}><path d={ARCO} /></clipPath>
      <g clipPath={`url(#${id}c)`}>
        <g transform={`translate(-300 0) scale(${hoja / 300} 1)`}><Hoja /></g>
        <g transform={`translate(300 0) scale(${-hoja / 300} 1)`}><Hoja /></g>
      </g>
    </g>
  );
};

// la puerta con su escalón y la palangana: sirve para inicio, lavado, final del médico y el lavamanos de hoy
const Escalon: React.FC<{cierre: number; id: string; agua?: number; glow?: number; nieve?: boolean; manos?: boolean; manosY?: number; sep?: number; puntos?: number; pOp?: number; basinY?: number; kick?: number}> = ({
  cierre, id, agua = 0, glow = 0, nieve = false, manos = false, manosY = 1130, sep = 120, puntos = 0, pOp = 1, basinY = 1290, kick = 0,
}) => (
  <Lienzo>
    <g transform={`translate(${kick} ${Math.abs(kick) * 0.4})`}>
      <rect x={-300} y={-400} width={1680} height={1800} fill="rgba(0,0,0,0.001)" />
      {Array.from({length: 20}).map((_, i) => <line key={i} x1={-200} y1={i * 90 - 100} x2={1300} y2={i * 90 - 100} stroke="rgba(70,55,30,0.2)" strokeWidth={4} />)}
      <Puerta cierre={cierre} id={id} />
      <rect x={-300} y={1330} width={1680} height={900} fill="#8E8670" />
      <rect x={-300} y={1330} width={1680} height={34} fill="#B0A88F" />
      <rect x={-300} y={1364} width={1680} height={8} fill="rgba(0,0,0,0.25)" />
      {nieve && <ellipse cx={540} cy={1440} rx={330} ry={50} fill="#F1F4F6" />}
      <Palangana x={540} y={basinY} sc={1.1} agua={agua} glow={glow} />
      {nieve && <ellipse cx={540} cy={basinY - 56 * 1.1 + 6} rx={150} ry={20} fill="#F1F4F6" opacity={0.9} />}
      {manos && (
        <>
          <Mano x={540 - sep} y={manosY} puntos={puntos} pOp={pOp} />
          <Mano x={540 + sep} y={manosY} espejo puntos={puntos} pOp={pOp} />
        </>
      )}
      {nieve && <Nieve n={44} />}
    </g>
  </Lienzo>
);

// ---- Sitio 1: puerta (E1-E2) ----
const PuertaA: React.FC = () => {
  const {s, spr, lin} = useS();
  const cierre = lin(ECHARON - 0.15, ECHARON + 0.1, 0, 1, Easing.in(Easing.cubic));
  const acerca = lin(MANOS - 0.15, MANOS + 0.5, 0, 1);
  const sale = lin(ECHARON - 0.1, ECHARON + 0.45, 0, 1, Easing.in(Easing.cubic));
  const kick = golpe(s, ECHARON + 0.1, 40, 6) * 16;
  const basinY = 1290 - Math.max(0, golpe(s, ECHARON + 0.1, 30, 7)) * 34;
  const mx = 190 - (1 - spr(IGNAZ, 13, 120)) * 360;
  const paradas = ord([
    {t: 0, x: 540, y: 1050, zoom: 1.0},
    {t: MANOS - 0.2, x: 540, y: 1060, zoom: 1.05},
    {t: MANOS + 0.3, x: 540, y: 1150, zoom: 1.7},
    {t: ECHARON - 0.05, x: 540, y: 1160, zoom: 1.75},
    {t: ECHARON + 0.3, x: 540, y: 1050, zoom: 0.95},
    {t: IGNAZ, x: 520, y: 1070, zoom: 1.0},
    {t: VIENA, x: 540, y: 1000, zoom: 1.15},
  ]);
  return (
    <AbsoluteFill style={{background: '#7A6A48'}}>
      <Camara paradas={paradas}>
        <Textura tipo="papel" base="linear-gradient(180deg, #B9AE8A, #8D8466 70%, #5E5640)" linea="rgba(60,45,20,0.3)" luz="rgba(255,235,190,0.22)" semilla={31} />
        <Escalon id="pa" cierre={cierre} manos manosY={780 + (1130 - 780) * acerca + Math.sin(s * 3) * 8 * (1 - acerca) - sale * 760} sep={330 + (120 - 330) * acerca} basinY={basinY} kick={kick} />
        <Lienzo>
          {s > IGNAZ - 0.1 && <Medico x={mx} y={1215} sc={0.9} enojo={0} />}
        </Lienzo>
        <Brillo x={540} y={1100} r={520} color="rgba(255,225,160,0.25)" />
      </Camara>
    </AbsoluteFill>
  );
};

// ---- Sitio 2: hospital (E3-E6) ----
const Fachada: React.FC = () => (
