  return (
    <Lienzo>
      <rect x={-300} y={-400} width={1680} height={1900} fill="#8F957E" />
      <rect x={-300} y={1440} width={1680} height={20} fill="#6B6F5B" />
      <polygon points="-300,1500 1380,1500 1380,2300 -300,2300" fill="#A59A78" />
      {Array.from({length: 13}).map((_, i) => <line key={i} x1={540} y1={1500} x2={i * 135 - 300} y2={2300} stroke="rgba(70,55,30,0.25)" strokeWidth={4} />)}
      <rect x={470} y={820} width={140} height={680} fill="#6B7060" />
      <rect x={490} y={860} width={100} height={640} fill="rgba(255,235,190,0.25)" />
      {[270, 810].map((dx, i) => (
