          <rect x={dx - 135} y={740} width={270} height={300} fill="rgba(0,0,0,0.18)" stroke="#3E2A16" strokeWidth={5} />
          <rect x={dx - 135} y={1080} width={270} height={360} fill="rgba(0,0,0,0.18)" stroke="#3E2A16" strokeWidth={5} />
          <circle cx={i ? dx - 120 : dx + 120} cy={1130} r={14} fill="#C9A24A" />
          <ellipse cx={dx} cy={620} rx={150} ry={90} fill="rgba(255,225,150,0.22)" />
